import{_ as t,o as r,c as a,ae as o}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"API Connection Problems","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/api-issues.md","filePath":"troubleshooting/api-issues.md"}'),i={name:"troubleshooting/api-issues.md"};function s(n,e,l,d,c,h){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="api-connection-problems" tabindex="-1">API Connection Problems <a class="header-anchor" href="#api-connection-problems" aria-label="Permalink to &quot;API Connection Problems&quot;">​</a></h1><p>If AI translation isn’t working, this page helps you diagnose provider/API issues.</p><h2 id="common-causes" tabindex="-1">Common causes <a class="header-anchor" href="#common-causes" aria-label="Permalink to &quot;Common causes&quot;">​</a></h2><ul><li>Missing or invalid API key</li><li>No internet connection</li><li>Provider rate limits or quota limits</li><li>Wrong model selected</li></ul><h2 id="quick-checks" tabindex="-1">Quick checks <a class="header-anchor" href="#quick-checks" aria-label="Permalink to &quot;Quick checks&quot;">​</a></h2><ol><li>Verify your API key in <a href="./../get-started/api-keys.html">Setting Up API Keys</a></li><li>Confirm you selected a <strong>provider</strong> and <strong>model</strong> in Settings (LLM/AI settings)</li><li>Try translating a single short segment (<code>Ctrl+T</code>)</li><li>Check whether your account has credits/quota</li></ol><h2 id="common-errors-and-fixes" tabindex="-1">Common errors and fixes <a class="header-anchor" href="#common-errors-and-fixes" aria-label="Permalink to &quot;Common errors and fixes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom / message</th><th>Likely cause</th><th>What to do</th></tr></thead><tbody><tr><td>“Invalid API key” / authentication failed</td><td>Key is wrong or has extra whitespace</td><td>Re-paste the key; make sure there are no leading/trailing spaces; Save and restart if needed</td></tr><tr><td>“Rate limit exceeded”</td><td>Provider is throttling requests</td><td>Wait 1–2 minutes; reduce batch size; try a different model</td></tr><tr><td>“Quota/credits exceeded”</td><td>Account has no credits or billing disabled</td><td>Check provider dashboard; add credits/enable billing</td></tr><tr><td>“Model not found”</td><td>Selected model name not available</td><td>Pick a supported model in Settings; update if the provider changed model names</td></tr><tr><td>“No response” / empty translation</td><td>Transient provider failure, network issue, or timeout</td><td>Try single-segment translation; retry the segment; try a different model/provider</td></tr><tr><td>Connection errors / timeouts</td><td>Network/VPN/firewall/proxy issues</td><td>Try another network; disable VPN; allow Python/Supervertaler through firewall</td></tr></tbody></table><h2 id="tips-for-reliable-translation" tabindex="-1">Tips for reliable translation <a class="header-anchor" href="#tips-for-reliable-translation" aria-label="Permalink to &quot;Tips for reliable translation&quot;">​</a></h2><ul><li>Start with <strong>single-segment</strong> translation to verify your setup before running batch.</li><li>If batch translation returns empty segments, enable the retry option in the batch dialog.</li><li>If your segments contain tags/placeholders, add a prompt rule to preserve them exactly.</li></ul><h2 id="error-messages" tabindex="-1">Error messages <a class="header-anchor" href="#error-messages" aria-label="Permalink to &quot;Error messages&quot;">​</a></h2><p>If you see an error dialog, copy the message and include it when asking for help.</p><p>Include:</p><ul><li>Provider + model</li><li>Whether single-segment translation works</li><li>The exact error text</li></ul>',14)]))}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
